export function validateResult(r){if(!r||typeof r.name!=='string'||!r.name.trim()||r.name.length>24||typeof r.emoji!=='string'||!r.emoji.trim()||r.emoji.length>24||typeof r.reason!=='string'||!r.reason.trim()||r.reason.length>200)throw Error('合成服務回傳格式不正確，請檢查 name、emoji、reason。');return {name:r.name.trim(),emoji:r.emoji.trim(),reason:r.reason.trim()};}
